SELECT "Motos_2"."Anunciante__grupo_" AS "Anunciante__grupo_",   MIN("Motos_2"."Vehiculo") AS "TEMP_attr_Vehiculo_nk__1662645443__0_",   MIN("Motos_2"."Vehiculo") AS "TEMP_attr_Vehiculo_nk__536654816__0_",   "Motos_2"."Vehiculo" AS "Vehiculo",   CAST(EXTRACT(MONTH FROM "Motos_2"."FECHA") AS BIGINT) AS "mn_FECHA_ok",   SUM((CAST("Motos_2"."Cols" AS BIGINT) * CAST("Motos_2"."Plgs" AS BIGINT))) AS "sum_Calculation_1450626233922327_ok",   SUM(CAST("Motos_2"."NumAnuncios" AS BIGINT)) AS "sum_NumAnuncios_ok" FROM "Motos_2" WHERE (("Motos_2"."Categoria" IN ('CAMIONES', 'CAMIONES, BUSES Y PANELES', 'MOTOCICLETAS', 'PICK UPS, VANS Y JEEPS', 'PICK-UPS', 'SUV Y JEEPS', 'VEHICULOS NUEVOS')) AND (CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) >= 2010) AND (CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) <= 2015) AND (CAST(EXTRACT(YEAR FROM "Motos_2"."FECHA") AS BIGINT) = 2015) AND ("Motos_2"."Categoria" = 'MOTOCICLETAS') AND ("Motos_2"."Medio" = 'PRENSA')) GROUP BY "Motos_2"."Anunciante__grupo_",   "Motos_2"."Vehiculo",   "mn_FECHA_ok";
